div.script:
var bookingState = {
    step: 1,
    patientType: 'new', // 'new' | 'returning'
    existingPatientId: null,
    serviceId: null,
    serviceName: '',
    serviceDuration: 30,
    doctorId: null,
    doctorName: 'Any Specialist',
    selectedDate: '',
    selectedSlotTime: null,
    selectedSlotLabel: '',
    hasInsurance: 'no'
};

// Initialize today's date
document.addEventListener('DOMContentLoaded', function() {
    var today = new Date();
    var yyyy = today.getFullYear();
    var mm = String(today.getMonth() + 1).padStart(2, '0');
    var dd = String(today.getDate()).padStart(2, '0');
    bookingState.selectedDate = yyyy + '-' + mm + '-' + dd;
    var datePicker = document.getElementById('booking_date_picker');
    if (datePicker) {
        datePicker.value = bookingState.selectedDate;
        datePicker.min = bookingState.selectedDate;
    }

    // Pre-select first service card if available
    var firstCard = document.querySelector('.type-grid-card');
    if (firstCard) {
        selectService(firstCard);
    }
});

function getCsrf() {
    var el = document.querySelector('input[name="csrf_token"]');
    return (el && el.value) ? el.value : '';
}

function showError(msg) {
    var alertBox = document.getElementById('flow_error_alert');
    var textEl = document.getElementById('flow_error_text');
    if (alertBox && textEl) {
        textEl.textContent = msg;
        alertBox.classList.remove('d-none');
        alertBox.classList.add('d-flex');
    }
}

function clearError() {
    var alertBox = document.getElementById('flow_error_alert');
    if (alertBox) {
        alertBox.classList.add('d-none');
        alertBox.classList.remove('d-flex');
    }
}

function updateStepperUI(stepNum) {
    for (var i = 1; i <= 5; i++) {
        var dot = document.getElementById('dot_step_' + i);
        var line = document.getElementById('line_step_' + (i - 1));
        if (dot) {
            dot.classList.remove('active', 'completed');
            if (i === stepNum) dot.classList.add('active');
            else if (i < stepNum) dot.classList.add('completed');
        }
        if (line) {
            line.classList.remove('active');
            if (i <= stepNum) line.classList.add('active');
        }
    }

    // Stepper header visibility
    var header = document.getElementById('flow_stepper_header');
    if (header) {
        if (stepNum >= 6) header.classList.add('d-none');
        else header.classList.remove('d-none');
    }

    // Summary pills visibility
    var pillsBar = document.getElementById('summary_pills_bar');
    if (pillsBar) {
        if (stepNum > 1 && stepNum < 6) {
            pillsBar.classList.remove('d-none');
            document.getElementById('pill_patient_type').textContent = bookingState.patientType === 'returning' ? 'Existing Patient' : 'New Patient';
            document.getElementById('pill_service_name').textContent = bookingState.serviceName || 'Consultation';

            var pillDoc = document.getElementById('pill_doctor_item');
            if (stepNum > 3) {
                pillDoc.classList.remove('d-none');
                document.getElementById('pill_doctor_name').textContent = bookingState.doctorName || 'Any Specialist';
            } else {
                pillDoc.classList.add('d-none');
            }

            var pillSlot = document.getElementById('pill_slot_item');
            if (bookingState.selectedSlotLabel) {
                pillSlot.classList.remove('d-none');
                document.getElementById('pill_slot_name').textContent = bookingState.selectedDate + ' at ' + bookingState.selectedSlotLabel;
            } else {
                pillSlot.classList.add('d-none');
            }
        } else {
            pillsBar.classList.add('d-none');
        }
    }
}

function goToStep(stepNum) {
    clearError();
    for (var i = 1; i <= 6; i++) {
        var pane = document.getElementById('pane_step_' + i);
        if (pane) pane.classList.add('d-none');
    }
    var target = document.getElementById('pane_step_' + stepNum);
    if (target) {
        target.classList.remove('d-none');
        bookingState.step = stepNum;
        updateStepperUI(stepNum);

        if (stepNum === 4) {
            fetchAvailableSlots();
        }

        // Scroll smoothly to top of wizard
        var container = document.querySelector('.flow-main-container');
        if (container) {
            container.scrollIntoView({ behavior: 'smooth', block: 'start' });
        }
    }
}

// Step 1: Patient Selection
function selectPatientType(type) {
    bookingState.patientType = type;
    var cardNew = document.getElementById('card_choice_new');
    var cardExt = document.getElementById('card_choice_existing');
    var boxSearch = document.getElementById('existing_patient_search_box');

    if (type === 'new') {
        cardNew.classList.add('selected');
        cardExt.classList.remove('selected');
        boxSearch.classList.add('d-none');
        bookingState.existingPatientId = null;
    } else {
        cardExt.classList.add('selected');
        cardNew.classList.remove('selected');
        boxSearch.classList.remove('d-none');
        document.getElementById('ret_search_identifier').focus();
    }
}

function lookupPatient() {
    var val = (document.getElementById('ret_search_identifier').value || '').trim();
    var msgEl = document.getElementById('ret_search_message');
    var prevEl = document.getElementById('ret_patient_preview');
    var iconSearch = document.getElementById('icon_search_patient');

    if (!val) {
        msgEl.className = 'small mt-2 text-danger';
        msgEl.textContent = 'Please enter a mobile phone number, email, or Patient ID.';
        msgEl.classList.remove('d-none');
        prevEl.classList.add('d-none');
        return;
    }

    iconSearch.className = 'fa fa-spinner fa-spin me-1';
    msgEl.className = 'small mt-2 text-muted';
    msgEl.textContent = 'Looking up patient records...';
    msgEl.classList.remove('d-none');

    fetch('/dental/check_patient', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'X-CSRFToken': getCsrf() },
        body: JSON.stringify({ jsonrpc: '2.0', method: 'call', params: { identifier: val } })
    })
    .then(function(r) { return r.json(); })
    .then(function(d) {
        iconSearch.className = 'fa fa-search me-1';
        var res = d.result || {};
        if (res.found) {
            bookingState.existingPatientId = res.id;
            msgEl.className = 'small mt-2 text-success fw-bold';
            msgEl.textContent = 'Patient record found and verified!';

            // Update preview card
            document.getElementById('prev_pat_name').textContent = res.name || '';
            document.getElementById('prev_pat_id').textContent = res.dental_patient_id || 'Registered';
            document.getElementById('prev_pat_phone').textContent = res.phone || '-';
            if (res.email) {
                document.getElementById('prev_pat_email_wrap').classList.remove('d-none');
                document.getElementById('prev_pat_email').textContent = res.email;
            } else {
                document.getElementById('prev_pat_email_wrap').classList.add('d-none');
            }
            prevEl.classList.remove('d-none');

            // Pre-fill Step 5 form
            var names = (res.name || '').split(' ');
            document.getElementById('inp_first_name').value = names[0] || '';
            document.getElementById('inp_last_name').value = names.slice(1).join(' ') || '';
            document.getElementById('inp_phone').value = res.phone || '';
            document.getElementById('inp_email').value = res.email || '';
            if (res.patient && res.patient.date_of_birth) {
                document.getElementById('inp_dob').value = res.patient.date_of_birth;
            }
            if (res.patient && res.patient.gender) {
                document.getElementById('inp_gender').value = res.patient.gender;
            }
        } else {
            msgEl.className = 'small mt-2 text-danger';
            msgEl.textContent = res.message || 'No record found. You can proceed as a New Patient.';
            prevEl.classList.add('d-none');
        }
    })
    .catch(function(err) {
        iconSearch.className = 'fa fa-search me-1';
        msgEl.className = 'small mt-2 text-danger';
        msgEl.textContent = 'Error contacting patient server. Please try again.';
    });
}

// Step 2: Service Selection
function selectService(card) {
    document.querySelectorAll('.type-grid-card').forEach(function(c) { c.classList.remove('selected'); });
    card.classList.add('selected');
    bookingState.serviceId = parseInt(card.getAttribute('data-id'));
    bookingState.serviceName = card.getAttribute('data-name');
    bookingState.serviceDuration = parseInt(card.getAttribute('data-duration')) || 30;

    document.getElementById('s4_dur_summary').textContent = bookingState.serviceDuration;
}

// Step 3: Doctor Selection
function selectDoctor(card) {
    document.querySelectorAll('.doctor-choice-card').forEach(function(c) { c.classList.remove('selected'); });
    card.classList.add('selected');
    var docId = card.getAttribute('data-id');
    bookingState.doctorId = docId ? parseInt(docId) : null;
    bookingState.doctorName = card.getAttribute('data-name') || 'Any Specialist';

    document.getElementById('s4_doctor_name_label').textContent = bookingState.doctorName;
    document.getElementById('s4_doctor_summary').textContent = bookingState.doctorName;
}

// Step 4: Slots Fetching
function fetchAvailableSlots() {
    var datePicker = document.getElementById('booking_date_picker');
    bookingState.selectedDate = datePicker.value || datePicker.min || bookingState.selectedDate;

    var loader = document.getElementById('slots_loading_indicator');
    var container = document.getElementById('slots_results_box');
    var noneMsg = document.getElementById('slots_none_message');
    var morningBox = document.getElementById('morning_slots_container');
    var afternoonBox = document.getElementById('afternoon_slots_container');
    var nextBtn = document.getElementById('btn_goto_step_5');

    morningBox.innerHTML = '';
    afternoonBox.innerHTML = '';
    bookingState.selectedSlotTime = null;
    bookingState.selectedSlotLabel = '';
    nextBtn.disabled = true;

    loader.classList.remove('d-none');
    noneMsg.classList.add('d-none');

    fetch('/dental/get_slots', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'X-CSRFToken': getCsrf() },
        body: JSON.stringify({
            jsonrpc: '2.0',
            method: 'call',
            params: {
                date: bookingState.selectedDate,
                doctor_id: bookingState.doctorId,
                duration: bookingState.serviceDuration
            }
        })
    })
    .then(function(r) { return r.json(); })
    .then(function(d) {
        loader.classList.add('d-none');
        var slots = (d.result && d.result.slots) ? d.result.slots : [];

        if (slots.length === 0) {
            noneMsg.classList.remove('d-none');
            return;
        }

        var morningCount = 0;
        var afternoonCount = 0;

        slots.forEach(function(slot) {
            var btn = document.createElement('button');
            btn.type = 'button';
            btn.className = 'slot-bubble-btn';
            btn.textContent = slot.label;
            btn.disabled = !slot.available;
            if (slot.available) {
                btn.onclick = function() {
                    document.querySelectorAll('.slot-bubble-btn').forEach(function(b) { b.classList.remove('selected'); });
                    btn.classList.add('selected');
                    bookingState.selectedSlotTime = slot.time;
                    bookingState.selectedSlotLabel = slot.label;
                    nextBtn.disabled = false;
                };
            }

            if (slot.period === 'morning') {
                morningBox.appendChild(btn);
                morningCount++;
            } else {
                afternoonBox.appendChild(btn);
                afternoonCount++;
            }
        });

        if (morningCount === 0) morningBox.innerHTML = '<span class="text-muted small">No morning slots available</span>';
        if (afternoonCount === 0) afternoonBox.innerHTML = '<span class="text-muted small">No afternoon slots available</span>';
    })
    .catch(function(err) {
        loader.classList.add('d-none');
        noneMsg.classList.remove('d-none');
    });
}

// Step 5: Insurance & Submit
function setInsuranceChoice(val) {
    bookingState.hasInsurance = val;
    var btnNo = document.getElementById('btn_ins_no');
    var btnYes = document.getElementById('btn_ins_yes');
    var wrap = document.getElementById('insurance_info_container');

    if (val === 'yes') {
        btnYes.classList.add('active');
        btnNo.classList.remove('active');
        wrap.classList.remove('d-none');
        document.getElementById('inp_insurance_info').focus();
    } else {
        btnNo.classList.add('active');
        btnYes.classList.remove('active');
        wrap.classList.add('d-none');
    }
}

function submitAppointmentBooking(e) {
    e.preventDefault();
    clearError();

    var fName = (document.getElementById('inp_first_name').value || '').trim();
    var lName = (document.getElementById('inp_last_name').value || '').trim();
    var phone = (document.getElementById('inp_phone').value || '').trim();
    var email = (document.getElementById('inp_email').value || '').trim();
    var dob = document.getElementById('inp_dob').value || '';
    var gender = document.getElementById('inp_gender').value || 'male';
    var zipCode = (document.getElementById('inp_zip_code').value || '').trim();
    var priority = document.getElementById('inp_priority').value || '1';
    var insInfo = bookingState.hasInsurance === 'yes' ? (document.getElementById('inp_insurance_info').value || '').trim() : '';
    var notes = (document.getElementById('inp_notes').value || '').trim();

    if (!fName || !phone) {
        showError('Please enter your full name and mobile phone number.');
        return;
    }

    if (!bookingState.selectedSlotTime) {
        showError('Please select an appointment time slot.');
        goToStep(4);
        return;
    }

    var submitBtn = document.getElementById('btn_submit_appointment');
    var iconSubmit = document.getElementById('icon_submit_btn');
    submitBtn.disabled = true;
    iconSubmit.className = 'fa fa-spinner fa-spin me-2';

    var payload = {
        name: fName + (lName ? (' ' + lName) : ''),
        first_name: fName,
        last_name: lName,
        phone: phone,
        email: email,
        dob: dob,
        gender: gender,
        zip_code: zipCode,
        priority: priority,
        has_insurance: bookingState.hasInsurance,
        insurance_info: insInfo,
        notes: notes,
        patient_type: bookingState.patientType,
        patient_id: bookingState.existingPatientId,
        appointment_type_id: bookingState.serviceId,
        doctor_id: bookingState.doctorId,
        // Keys read by dental.appointment.create_appointment_booking
        appointment_date: bookingState.selectedDate,
        appointment_time: bookingState.selectedSlotTime,
        duration: bookingState.serviceDuration
    };
    // Extension point: add-ons may add booking values (e.g. the online consultation mode)
    document.dispatchEvent(new CustomEvent('dental:booking-submit', { detail: payload }));

    fetch('/dental/book_appointment', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'X-CSRFToken': getCsrf() },
        body: JSON.stringify({ jsonrpc: '2.0', method: 'call', params: payload })
    })
    .then(function(r) { return r.json(); })
    .then(function(d) {
        submitBtn.disabled = false;
        iconSubmit.className = 'fa fa-check-circle me-2';

        var res = d.result || {};
        if (res.success) {
            var appt = res;
            document.getElementById('res_succ_ref').textContent = appt.appointment_name || 'APT-00000';
            document.getElementById('res_succ_patient').textContent = (appt.patient_name || payload.name) + (appt.patient_id ? (' (' + appt.patient_id + ')') : '');
            document.getElementById('res_succ_doctor').textContent = appt.doctor_name || bookingState.doctorName;
            document.getElementById('res_succ_service').textContent = appt.service_name || bookingState.serviceName;
            document.getElementById('res_succ_datetime').textContent = (appt.date_formatted || bookingState.selectedDate) + ' at ' + (appt.time_formatted || bookingState.selectedSlotLabel);

            goToStep(6);
            // Extension point: add-ons may adapt the success screen to the server result
            document.dispatchEvent(new CustomEvent('dental:booking-success', { detail: res }));
        } else {
            showError(res.error || res.message || 'Booking submission failed. Please try again.');
        }
    })
    .catch(function(err) {
        submitBtn.disabled = false;
        iconSubmit.className = 'fa fa-check-circle me-2';
        showError('A network error occurred while submitting your booking. Please try again.');
    });
}

function restartBookingFlow() {
    bookingState.existingPatientId = null;
    bookingState.selectedSlotTime = null;
    bookingState.selectedSlotLabel = '';
    selectPatientType('new');
    document.getElementById('public_booking_form').reset();
    goToStep(1);
}

// Explicitly bind to window for global access
window.bookingState = bookingState;
window.getCsrf = getCsrf;
window.showError = showError;
window.clearError = clearError;
window.updateStepperUI = updateStepperUI;
window.goToStep = goToStep;
window.selectPatientType = selectPatientType;
window.lookupPatient = lookupPatient;
window.selectService = selectService;
window.selectDoctor = selectDoctor;
window.fetchAvailableSlots = fetchAvailableSlots;
window.setInsuranceChoice = setInsuranceChoice;
window.submitAppointmentBooking = submitAppointmentBooking;
window.restartBookingFlow = restartBookingFlow;
